	throw error_exception(str);
}

int real_my_method(int a, char *b) {
	/*
	some code...
	*/
	return 0;
}

// this is the public method:
int my_method(int a, char *b) {
	try {
		return real_my_method(a, b);
	}
	catch (error_exception &e) {
		error(e.msg);
	}
}

